+static int dissect_ebhscr_dsi3(tvbuff_t *tvb, packet_info *pinfo, proto_tree *tree, proto_tree *ebhscr_packet_header_tree,
+								proto_item *ebhscr_channel, uint16_t ebhscr_status, uint32_t ebhscr_frame_length)
+{
+	proto_item *ti;
