+	dsi3_status_tree = proto_item_add_subtree(ti, ett_ebhscr_status);
+	proto_tree_add_bitmask_list(dsi3_status_tree, tvb, 2, 2, dsi3_status_bits, ENC_BIG_ENDIAN);
